import{_ as r,I as t,c as n,o,j as e,ap as d,a as l,J as h}from"./chunks/framework.BVMg0REN.js";const x=JSON.parse('{"title":"设置界面","description":"","frontmatter":{},"headers":[],"relativePath":"Features/Settings.md","filePath":"zh/Features/Settings.md","lastUpdated":1786237228000}'),s={name:"Features/Settings.md"},c={id:"设置界面",tabindex:"-1"};function u(p,a,m,b,f,P){const i=t("Badge");return o(),n("div",null,[e("h1",c,[a[0]||(a[0]=l("设置界面")),h(i,{type:"warning",text:"设置"}),a[1]||(a[1]=l()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#设置界面","aria-label":"Permalink to “设置界面”"},"​",-1))]),a[3]||(a[3]=d('<h2 id="定时执行" tabindex="-1">定时执行 <a class="header-anchor" href="#定时执行" aria-label="Permalink to “定时执行”">​</a></h2><p>可设定定时时间，需保证<code>MaaYuan</code>为开启状态，到达时间后会自动执行对应实例中勾选的任务。每个实例所对应的定时执行是独立的，如需要定时执行不同任务，请新建多个实例并勾选所需任务。</p><ul><li>强制定时启动：勾选后会重启模拟器并开始任务，需在 “设置-启动设置” 中填写好模拟器的启动路径等，详见<a href="./../Features/Settings.html#启动设置">【启动设置】</a>。</li></ul><h2 id="性能设置" tabindex="-1">性能设置 <a class="header-anchor" href="#性能设置" aria-label="Permalink to “性能设置”">​</a></h2><p>GPU加速开关，可自行调整。</p><h2 id="运行设置" tabindex="-1">运行设置 <a class="header-anchor" href="#运行设置" aria-label="Permalink to “运行设置”">​</a></h2><ul><li>实时视图：实时监控模拟器视图开关，开启后会在主任务界面及控制台界面监控到模拟器实时画面，会占用一部分运存，可自行调整。</li><li>实时视图最高刷新率：监控视图刷新率设置，自行调整。 其余项如非必要不建议调整。</li></ul><h2 id="连接设置" tabindex="-1">连接设置 <a class="header-anchor" href="#连接设置" aria-label="Permalink to “连接设置”">​</a></h2><ul><li>捕获方式&amp;触控模式：<code>MaaYuan</code>截图及点击的方式，如遇到点击/运行问题，可更换其他选项尝试。</li><li>记住连接：开启后会记录当前连接的模拟器信息，推荐开启。</li><li>连接失败后相关设置：根据自身情况调整，如需要<code>MaaYuan</code>在多开模式下启动模拟器，请开启“ADB连接失败时尝试启动模拟器”功能，详见<a href="./../Features/Settings.html#启动设置">【启动设置】</a>。</li></ul><h2 id="启动设置" tabindex="-1">启动设置 <a class="header-anchor" href="#启动设置" aria-label="Permalink to “启动设置”">​</a></h2><p>可设置模拟器路径，设置完成后，<code>MaaYuan</code>将在特定情况下（如开启“启动时操作”/“ADB连接失败时尝试启动模拟器”功能）打开模拟器。</p><ul><li>启动时&amp;结束后操作：<code>MaaYuan</code>启动及任务结束后的操作，根据自身情况调整。（注意：该部分设置仅在单个实例模式下生效，有多个实例的情况下无效）</li><li>模拟器路径：填写/点击输入框右侧的打开按钮，选择模拟器安装路径中的启动文件，如MuMu模拟器为“MuMuNxMain.exe”（TIP：可选桌面快捷方式）。</li><li>附加命令：多开模拟器时填写，如不清楚填写规则，可点击“多开快捷设置”进行选择。</li><li>等待模拟器启动时间：自行填写，默认等待60s。</li></ul><h2 id="界面设置" tabindex="-1">界面设置 <a class="header-anchor" href="#界面设置" aria-label="Permalink to “界面设置”">​</a></h2><p>可调整<code>MaaYuan</code>的界面等个性化操作，包括：</p><ul><li>主题色</li><li>背景图片设置</li><li>应用程序显示语言</li><li>界面字体大小缩放</li><li>最小化设置</li><li>通知开关</li></ul><h2 id="外部通知" tabindex="-1">外部通知 <a class="header-anchor" href="#外部通知" aria-label="Permalink to “外部通知”">​</a></h2><p>支持任务完成后发送“任务已全部完成”或自定义内容的通知。</p><h3 id="钉钉" tabindex="-1">钉钉 <a class="header-anchor" href="#钉钉" aria-label="Permalink to “钉钉”">​</a></h3><ul><li>电脑端钉钉建群并添加自定义机器人：群设置 → 机器人 → 添加机器人 → 自定义 → 添加。</li><li>安全设置选“加签”，复制记录密钥和 webhook 地址。</li><li>打开<code>MaaYuan</code>→ 设置 → 外部通知 → 开启钉钉通知，将密钥和地址分别粘贴至对应位置：</li><li>机器人 Token = webhook 地址</li><li>钉钉 Secret = 密钥</li><li>可选填自定义内容，点击“发送测试”验证。</li></ul><h3 id="邮箱-以qq邮箱为例" tabindex="-1">邮箱（以QQ邮箱为例） <a class="header-anchor" href="#邮箱-以qq邮箱为例" aria-label="Permalink to “邮箱（以QQ邮箱为例）”">​</a></h3><ul><li>登录邮箱网页端，进入设置 → 账号与安全 → POP3/IMAP/SMTP/Exchange/CardDAV 服务，开启服务并生成授权码（不同邮箱步骤类似）。</li><li>复制授权码，粘贴至<code>MaaYuan</code>指定位置，点击“发送测试”接收验证通知。</li><li>机器人 Token = 你的 QQ 邮箱账号</li><li>邮箱 Secret = 生成的授权码</li></ul><h3 id="微信公众号" tabindex="-1">微信公众号 <a class="header-anchor" href="#微信公众号" aria-label="Permalink to “微信公众号”">​</a></h3><p>详细请查阅<a href="http://xhslink.com/o/2SaSzk8ARoD" target="_blank" rel="noreferrer">用微信公众号接收任务完成消息教程</a></p><h2 id="热键设置" tabindex="-1">热键设置 <a class="header-anchor" href="#热键设置" aria-label="Permalink to “热键设置”">​</a></h2><p>此项全局生效，包括：</p><ul><li>显示/隐藏软件</li><li>开始/停止任务</li></ul><h2 id="更新设置" tabindex="-1">更新设置 <a class="header-anchor" href="#更新设置" aria-label="Permalink to “更新设置”">​</a></h2><p>详细请查阅<a href="./../Started/ConnectionAndUpdate.html">快速开始-连接与更新</a></p>',28))])}const _=r(s,[["render",u]]);export{x as __pageData,_ as default};
